-- 136: four US parks from Carter's RCDB screenshots, 2026-11-05. All pins are
-- ESTIMATES, listed in missing-parks.md until Carter sends real ones.
-- Wonderland Amusement Park (Amarillo): Cyclone (Miler wild mouse, 1968), Hornet
--   (custom Vekoma MK-700, 2009-06-03), Mouse Trap (Pinfari Zyklon Z64, 1975),
--   Texas Tornado (Hopkins looper, 1985; not AstroWorld's Schwarzkopf one).
--   Spin-o-Saurus, which RCDB says ran here before Zao Island, is left out:
--   no dates for its time here.
-- Castles N' Coasters (Phoenix): Desert Storm (Hopkins, 2 loops) and Patriot
--   (Hopkins), both 1992.
-- Keansburg Amusement Park: Looping Star (Pinfari Zyklon ZL42, 2015-07-05),
--   Sea Serpent (Miler 16ft family spiral, 1998), Wild Cat (Schwarzkopf Wildcat
--   65m, 1984-2012).
-- Jenkinson's Boardwalk (Point Pleasant Beach): Patriot's Run (SBF Cyclon MX49,
--   2026-05-30), Shark Escape (SBF Double Coaster MX605, 2022-06-30), Tidal Wave
--   (SBF spinner, 4/2019-9/2025), Flitzer (Zierer, 1992-2018), Tornado (Zamperla
--   powered helix, 1995-2021).
-- Relocations linked where the old home is already here and the stats match
--   exactly: Hornet = AstroWorld's Mayan Mindbender (27.9 ft, 1,148.3 ft), and
--   Keansburg's Looping Star = Beech Bend's (36.1 ft, 1,197.5 ft). The running
--   copy is the home. Safe to run twice.
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Hornet' AND h.park = 'Wonderland Amusement Park' AND (c.id = h.id OR (c.name = 'Mayan Mindbender' AND c.park = 'Six Flags AstroWorld'));
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Looping Star' AND h.park = 'Keansburg Amusement Park' AND (c.id = h.id OR (c.name = 'Looping Star' AND c.park = 'Beech Bend'));
UPDATE parks SET travel = 0 WHERE name IN ('Wonderland Amusement Park','Castles N'' Coasters','Keansburg Amusement Park','Jenkinson''s Boardwalk') AND travel IS NULL;
